      elsif( addr_cntr_reg (20 downto 18) = "001") then
        data_dummy <= OVERLAY_RAM2(conv_integer(addr_cntr_reg (17 downto 0)));
      elsif( addr_cntr_reg (20 downto 18) = "010") then
        data_dummy <= OVERLAY_RAM3(conv_integer(addr_cntr_reg (17 downto 0)));
      elsif( addr_cntr_reg (20 downto 18) = "011") then
        data_dummy <= OVERLAY_RAM4(conv_integer(addr_cntr_reg (17 downto 0)));
      elsif( addr_cntr_reg (20 downto 18) = "100") then
        data_dummy <= OVERLAY_RAM5(conv_integer(addr_cntr_reg (17 downto 0)));
      else
        data_dummy <= "0";
      end if;
  end if;  
end process;

-- Assign output
OVERLAY_O <= data_dummy(0);

end Behavioral;


